draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    let x = W / 2 + i * 30 + 20 * Math.sin(t + i);
    let y = H / 2 + 10 * Math.cos(t + i * 1.5);
    ctx.lineTo(x, y);
  }
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    let x = W / 2 + i * 30 + 20 * Math.sin(t + i);
    let y = H / 2 + 10 * Math.cos(t + i * 1.5);
    ctx.beginPath();
    ctx.arc(x, y, 5, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.lineWidth = 2;
  ctx.moveTo(W / 2 - 150, H / 2);
  ctx.lineTo(W / 2 + 150, H / 2);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('BREAK', W / 2, H / 2 - 50);
  ctx.restore();
}
